function ChannelPageInner() {
  const { id: rawId } = useParams({ from: "/channels/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.channels.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["channels"]["update"]) => client.channels.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["channels"]["delete"]) => client.channels.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/channels" });
    }
  });
  const joinAction = useMutation({
    mutationFn: (input: Inputs["channels"]["join"]) => client.channels.join(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} signIn={<Link to="/login" className={buttonVariants()}>Sign in</Link>} />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "Channel " + text(row.id)}
      actions={
        <>
          <Link to="/channels" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canJoin(user, row) ? (
            <Button variant="outline" size="sm" disabled={joinAction.isPending} onClick={() => joinAction.mutate({ id })}>
              Join
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this channel?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={joinAction.error} className="mb-4" />
      {editing ? (
        <ChannelForm
          fields={CHANNEL_UPDATE}
          initial={channelFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toChannelUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Private">{row.private == null ? "—" : <Badge variant={row.private ? "default" : "outline"}>{yesNo(row.private)}</Badge>}</FieldRow>
        <FieldRow label="Team">{user !== null ? <Link to="/teams/$id" params={{ id: text(row.team_id) }} className="hover:underline">{text(row.team_id) || "—"}</Link> : text(row.team_id) || "—"}</FieldRow>
        <FieldRow label="Created By">{text(row.created_by) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
      <ChannelMessagesSection key={text(row.id)} id={id} user={user} />
      <ChannelChannelMembersSection key={text(row.id)} id={id} user={user} />
      <ChannelChannelInvitesSection key={text(row.id)} id={id} user={user} />
    </Pane>
  );
}

export const ChannelPage = guarded(ChannelPageInner);
